 void SetManagementEnabled(bool enabled){if(playersPage==null)return;playersPage.IsEnabled=botControlCard.IsEnabled=enabled;navPlayers.IsEnabled=enabled;}
 async Task ManagedWork(string title,Func<Task> work){await Work(title,async()=>{await work();await RefreshManagementAsync(true);});}
 async Task MapCommandAsync(string action){if(managementState?["online"]?.GetValue<bool>()!=true){ShowNotice("游戏服未连接","先启动游戏服再进行对局操作。",true);return;}var map=liveMapCombo.SelectedItem as LiveMapChoice;if(action is "switch" or "queue"&&map==null){ShowNotice("请选择地图","从服务器当前轮换中选择地图。",true);return;}if(action!="queue"&&MessageBox.Show("此操作会结束或重置当前回合，是否继续？","对局控制",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;await ManagedWork("执行对局操作",async()=>{await backend.ManagementAsync("map",new JsonObject{["action"]=action,["index"]=map?.Index??0,["revision"]=managementState?["mapRevision"]?.DeepClone()});});}
