 string? MInput(string title,string hint,int max=120,string initial=""){var win=new Window{Owner=this,Title=title,Width=520,Height=235,WindowStartupLocation=WindowStartupLocation.CenterOwner,ResizeMode=ResizeMode.NoResize,Background=Background,FontFamily=FontFamily};var p=new StackPanel{Margin=new Thickness(24)};win.Content=p;p.Children.Add(MText(hint));var box=new TextBox{Text=initial,MaxLength=max};p.Children.Add(box);string? answer=null;var buttons=MRow();buttons.Children.Add(MButton("确定",()=>{if(string.IsNullOrWhiteSpace(box.Text))return;answer=box.Text.Trim();win.DialogResult=true;},true));buttons.Children.Add(MButton("取消",()=>win.Close()));p.Children.Add(buttons);win.ShowDialog();return answer;}
 async Task SaveFillAsync(bool restart){await ManagedWork("保存人机数量",async()=>{if(!backend.Initialized)throw new Exception("请先完成初始化。");var mode=fillMode.SelectedIndex;var body=new JsonObject{["enabled"]=mode!=0,["mode"]=mode==2?"teams":"auto",["target"]=mode==1?Integer(fillTarget,1,64,"目标总人数"):64,["reserve"]=mode==1?Integer(fillReserve,0,8,"预留空位"):1,["team1"]=mode==2?Integer(fillTeam1,0,64,"队伍一人机"):0,["team2"]=mode==2?Integer(fillTeam2,0,64,"队伍二人机"):0};if(mode==0){body["target"]=64;body["reserve"]=1;body["team1"]=0;body["team2"]=0;repo.Config.Server["initialBots"]=JsonValue.Create(Integer(fixedBots,0,63,"固定人机数量"));repo.Save();}await backend.ManagementAsync("save-fill",body);fillDirty=false;if(restart){if(MessageBox.Show("保存进度并重启游戏服以应用人数设置？","人机控制",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;await backend.Control("RestartGame");}else{backend.EnsureWatcher();Log(mode==0?"固定人机数量已保存，下次开服或重启游戏服应用。":"实时人机设置已保存，等待游戏服确认。");}});}
 async Task RefreshManagementAsync(bool force){if(playersPage==null||managementRefreshing)return;managementRefreshing=true;try{
  managementState=await backend.ManagementAsync("state");var state=managementState;bool online=state?["online"]?.GetValue<bool>()==true;onlinePlayers.Clear();foreach(var p in state?["players"]?.AsArray()??new JsonArray()){if(p==null)continue;int.TryParse(p["teamId"]?.ToString(),out int team);onlinePlayers.Add(new ManagedPlayer{Name=p["name"]?.ToString()??"",Guid=p["guid"]?.ToString()??"",Kind=string.IsNullOrEmpty(p["guid"]?.ToString())&&p["type"]?.ToString()=="0"?"人机":"真人",Team=team,Kills=p["kills"]?.ToString()??"0",Deaths=p["deaths"]?.ToString()??"0",Score=p["score"]?.ToString()??"0",Rank=p["rank"]?.ToString()??"—",Ping=p["ping"]?.ToString()??"—",Address=p["radminIp"]?.ToString()??"—",Raw=p.DeepClone()});}
  FilterPlayers();playersSummary.Text=online?$"当前 {onlinePlayers.Count} 人 · 真人 {onlinePlayers.Count(p=>p.Kind=="真人")} / 人机 {onlinePlayers.Count(p=>p.Kind=="人机")}":"游戏服未连接，启动后显示在线玩家。";
  int previous=(liveMapCombo.SelectedItem as LiveMapChoice)?.Index??-1;var maps=new List<LiveMapChoice>();foreach(var m in state?["maps"]?.AsArray()??new JsonArray()){if(m==null)continue;var id=m["map"]?.ToString()??"";maps.Add(new(){Index=m["index"]?.GetValue<int>()??maps.Count,Map=id,Label=(repo.Maps.FirstOrDefault(x=>x.Id==id)?.Label??id)+" · "+(m["rounds"]?.ToString()??"1")+" 回合"});}liveMapCombo.ItemsSource=maps;liveMapCombo.SelectedItem=maps.FirstOrDefault(x=>x.Index==previous)??maps.FirstOrDefault();liveMapStatus.Text=online?"当前："+(repo.Maps.FirstOrDefault(x=>x.Id==state?["map"]?.ToString())?.Label??state?["map"]?.ToString())+" · "+state?["gameState"]?.ToString():"等待游戏服连接。";
  var fill=state?["fill"];if(fill!=null){loadingFill=true;if(!fillDirty){fillMode.SelectedIndex=fill["enabled"]?.GetValue<bool>()==true?(fill["mode"]?.ToString()=="teams"?2:1):0;fillTarget.Text=fill["target"]?.ToString()??"64";fillReserve.Text=fill["reserve"]?.ToString()??"1";fillTeam1.Text=fill["team1"]?.ToString()??"0";fillTeam2.Text=fill["team2"]?.ToString()??"0";fixedBots.Text=repo.Config.Server.GetValueOrDefault("initialBots")?.ToString()??"31";}loadingFill=false;RefreshFillInputs();fillStatus.Text=fill["error"]?.ToString()??(fill["enabled"]?.GetValue<bool>()==true?"实时人机控制："+FillLabel(fill["state"]?.ToString()):"固定数量模式 · 下次开服应用；实时补位/分队在对局中调整。");}
