 void RefreshFillInputs(){if(fixedBots==null)return;fixedBots.IsEnabled=fillMode.SelectedIndex==0;fillTarget.IsEnabled=fillReserve.IsEnabled=fillMode.SelectedIndex==1;fillTeam1.IsEnabled=fillTeam2.IsEnabled=fillMode.SelectedIndex==2;}
