 void FilterPlayers(){if(playersTable==null)return;var selected=(playersTable.SelectedItem as ManagedPlayer)?.Name;var q=playerSearch?.Text.Trim()??"";playersTable.ItemsSource=onlinePlayers.Where(p=>p.Name.Contains(q,StringComparison.OrdinalIgnoreCase)).OrderBy(p=>p.Team is 1 or 2?p.Team:3).ToList();playersTable.SelectedItem=onlinePlayers.FirstOrDefault(x=>x.Name==selected);}
 async Task PlayerCommandAsync(string action){if(playersTable.SelectedItem is not ManagedPlayer p){ShowNotice("请选择玩家","先选择一名在线玩家。",true);return;}string? reason="";if(action=="kick"){reason=MInput("踢出玩家","填写踢出 "+p.Name+" 的原因。");if(reason==null)return;}else if(MessageBox.Show((action=="move"?"将玩家换边并重生：":"强制击杀玩家：")+p.Name+"？","玩家操作",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;await ManagedWork("执行玩家操作",async()=>{await backend.ManagementAsync("player",new JsonObject{["action"]=action,["name"]=p.Name,["guid"]=p.Guid,["reason"]=reason});});}
 async Task KillGroupAsync(int? team){var targets=onlinePlayers.Where(p=>p.Team is 1 or 2&&(!team.HasValue||p.Team==team)).ToList();if(targets.Count==0)return;if(MessageBox.Show("将强制击杀 "+targets.Count+" 名对战玩家，是否继续？","批量操作",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;await ManagedWork("执行批量击杀",async()=>{var a=new JsonArray();foreach(var p in targets)a.Add(new JsonObject{["name"]=p.Name,["guid"]=p.Guid,["teamId"]=p.Team});var result=await backend.ManagementAsync("kill",new JsonObject{["scope"]=team.HasValue?"team":"all",["team"]=team??0,["targets"]=a});var message=result?["message"]?.ToString()??"批量操作已返回。";Log(message);SetCompletion("批量玩家操作",message,result?["failed"]?.GetValue<int>()>0);});}
 async Task LoadProfilesAsync(){await ManagedWork("读取玩家档案",async()=>{var s=await backend.ManagementAsync("profiles");profilesTable.ItemsSource=(s?["players"]?.AsArray()??new JsonArray()).Where(x=>x!=null).Select(x=>new ManagedProfile{Id=x!["id"]?.ToString()??"",Name=x["name"]?.ToString()??"",IsBot=x["isBot"]?.GetValue<bool>()==true,Kind=x["isBot"]?.GetValue<bool>()==true?"人机":"真人",Rank=x["rank"]?.ToString()??"0",Experience=x["experience"]?.ToString()??"0",Kills=x["kills"]?.ToString()??"0",Deaths=x["deaths"]?.ToString()??"0"}).ToList();profileStatus.Text="档案分区："+s?["address"]?.ToString()+" · 修改前自动备份。";});}
 async Task EditProfileAsync(){if(profilesTable.SelectedItem is not ManagedProfile p){ShowNotice("请选择档案","先刷新并选择一个玩家档案。",true);return;}if(managementState?["online"]?.GetValue<bool>()==true||managementState?["blazeReachable"]?.GetValue<bool>()==true){ShowNotice("请先停止服务","停止游戏服和登录服务后再修改等级／经验。",true);return;}await ManagedWork("读取等级信息",async()=>{var snapshot=await backend.ManagementAsync("level-editor");var target=snapshot?["players"]?.AsArray().FirstOrDefault(x=>x?["id"]?.ToString()==p.Id&&x?["isBot"]?.GetValue<bool>()==p.IsBot)??throw new Exception("档案已变化，请刷新。");var dialog=new ProfileLevelWindow(p.Name,target,snapshot!["rankScores"]!.AsArray()){Owner=this};if(dialog.ShowDialog()!=true)return;await backend.ManagementAsync("profile-level",new JsonObject{["id"]=p.Id,["isBot"]=p.IsBot,["address"]=snapshot["address"]?.DeepClone(),["token"]=target["token"]?.DeepClone(),["experience"]=dialog.Experience});profileStatus.Text="等级和经验已保存，原档案已备份；重新开服登录后生效。";});}
 void BuildBotRuleCards(){ServerFields.Children.Add(MCard("人机对真人伤害",out var damage));damage.Children.Add(MText("仅调整人机对真人的伤害，和全局子弹伤害分开；0～200%，每档10%。应用后从下一次命中开始计算，不改变已扣除的生命值。"));var row=MRow();botDamageBox=MNumber(row,"伤害百分比","100");row.Children.Add(MButton("读取伤害",()=>_ = LoadDamageAsync()));row.Children.Add(MButton("应用伤害",()=>_ = ApplyDamageAsync(),true));damage.Children.Add(row);damageStatus=MText("默认100%；应用后回读生效状态。");damage.Children.Add(damageStatus);ServerFields.Children.Add(MCard("人机装备限制",out var loadout));loadout.Children.Add(MText("按类别或具体装备禁止人机使用；支持禁爆裂物、限制枪械和空手人机预设，真人装备不受影响。"));loadout.Children.Add(MButton("编辑装备限制",()=>_ = EditLoadoutAsync()));loadoutStatus=MText("保存后重启游戏服应用；人机载具开关与基础设置共用。 ");loadout.Children.Add(loadoutStatus);}
 async Task LoadDamageAsync(){await ManagedWork("读取人机伤害",async()=>{damageState=await backend.ManagementAsync("damage");botDamageBox.Text=damageState?["percent"]?.ToString()??"100";damageStatus.Text=damageState?["message"]?.ToString()??"伤害设置已读取。";});}
