 async Task EditLoadoutAsync(){await ManagedWork("读取人机装备",async()=>{var snapshot=await backend.ManagementAsync("loadout")??throw new Exception("未读取到装备规则。");var dialog=new LoadoutWindow(snapshot){Owner=this};if(dialog.ShowDialog()!=true)return;var body=new JsonObject{["revision"]=snapshot["revision"]?.DeepClone(),["policy"]=dialog.Policy,["botVehicles"]=dialog.Unarmed?false:snapshot["botVehicles"]?.GetValue<bool>()??true};await backend.ManagementAsync("save-loadout",body);repo.Config.Server["botVehicles"]=body["botVehicles"]?.DeepClone();var editor=fieldEditors.FirstOrDefault(x=>x.Field.Id=="botVehicles");if(editor?.Control is CheckBox cb)cb.IsChecked=body["botVehicles"]!.GetValue<bool>();repo.Save();loadoutStatus.Text=dialog.Unarmed?"空手人机已保存，人机载具已关闭；重启游戏服应用。":"装备限制已保存，重启游戏服应用。";if(dialog.Restart)await backend.Control("RestartGame");});}
